  "questions": [
    {
      "text": "Which of the following accurately describes the flow of tasks in the JavaScript event loop, considering both microtasks and macrotasks?" ,
      "answers": [
        {
          "text": "Microtasks are executed before macrotasks.",
          "explanation": "This statement is true because microtasks, such as those from Promises and setImmediate, are processed first within each cycle of the event loop before macrotasks, such as setTimeout and I/O operations.",
          "isCorrect": true
        },
        {
          "text": "Macrotasks are always executed before microtasks.",
          "explanation": "This statement is false because microtasks are processed before macrotasks in each event loop cycle.",
          "isCorrect": false
        },
        {
          "text": "Tasks are processed in random order without any specific priority.",
          "explanation": "This statement is false because there is a defined order of task processing based on their type (microtasks vs macrotasks).",
          "isCorrect": false
        },
        {
          "text": "All tasks are processed sequentially in the same order they were created.",
          "explanation": "This statement is false because tasks are not processed sequentially; rather, they are managed through the event loop and its queues.",
          "isCorrect": false
        }
      ]
    }
  ]
}
